class Solution {
public:
    int countDistinctIntegers(vector<int>& nums) {
        unordered_set<int> s;
        for (int x : nums) {
            s.insert(x);
            int rev = 0, t = x;
            while (t > 0) {
                rev = rev * 10 + t % 10;
                t /= 10;
            }
            s.insert(rev);
        }
        return (int)s.size();
    }
};
